sys_script_client.script:
function onLoad() {

    var ga = new GlideAjax('JAKScriptInclude_Utils');
    ga.addParam('sysparm_name', 'getUserName');
    ga.addParam('sysparm_userSysId', g_form.getValue('caller_id'));
    ga.getXMLAnswer(function(response) {
        var user = JSON.parse(response);
        g_form.addInfoMessage(
            'Name: ' + user.first_name + ' ' + user.last_name +
            ' | Email: ' + user.email +
            ' | Department: ' + user.department
        );
    });

	var gb = new GlideAjax('JAKScriptInclude_Utils');
	gb.addParam('sysparm_name', 'getCICount');
    gb.addParam('sysparm_CICountSysId', g_form.getValue('cmdb_ci'));
	gb.getXMLAnswer(function(response) {
		//g_form.addInfoMessage(response);
		// g_form.setValue('cmdb_ci', 'Count of similar CI : ' + response);
		g_form.showFieldMsg('cmdb_ci', 'Count of similar CI : ' + response, 'info');
	});

}
